const EXAMPLE_SEQUENCE = ['M', 'S', 'M', 'S', 'M', 'S'];
const DUMMY_COLOUR = '#767676';

const ROWS = [
  {
    label: 'star-only',
    mapping: { M: 'square', S: 'star' },
  },
  {
    label: 'dot-only',
    mapping: { M: 'dot', S: 'square' },
  },
  {
    label: 'tone-only',
    mapping: { M: 'tone', S: 'square' },
  },
  {
    label: 'star-dot (dual)',
    mapping: { M: 'dot', S: 'star' },
  },
  {
    label: 'star-tone (dual)',
    mapping: { M: 'tone', S: 'star' },
  },
];

function injectStyles() {
  const style = document.createElement('style');
  style.textContent = `
    #slot-sequence-figure {
      width: 1880px;
      margin: 0 auto;
      padding: 28px 30px;
      font-family: "Times New Roman", Times, serif;
      color: #111;
    }

    .slot-shell {
      border: 1.5px solid #111;
      background: #fff;
      padding: 26px 30px 24px;
    }

    .slot-title {
      margin: 0 0 14px;
      text-align: center;
      font-size: 30px;
      line-height: 1.1;
      font-weight: 600;
    }

    .slot-row {
      display: grid;
      grid-template-columns: 240px 1fr;
      gap: 20px;
      align-items: center;
      margin-bottom: 18px;
    }

    .slot-row:last-child {
      margin-bottom: 0;
    }

    .slot-row-header {
      margin-bottom: 8px;
    }

    .slot-label {
      font-size: 30px;
      font-weight: 700;
      line-height: 1.08;
      text-align: left;
    }

    .slot-header-strip {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 0;
      padding: 0 12px;
    }

    .slot-header-cell {
      text-align: center;
      font-size: 22px;
      font-weight: 600;
      line-height: 1;
    }

    .slot-lane {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 0;
      border: 1.4px solid #222;
      border-radius: 24px;
      background: #fbfbfb;
      overflow: hidden;
      min-height: 96px;
    }

    .slot-cell {
      display: grid;
      justify-items: center;
      align-items: center;
      padding: 18px 6px;
      border-right: 1px solid #d2d2d2;
    }

    .slot-cell:last-child {
      border-right: none;
    }

    .slot-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
    }
  `;
  document.head.appendChild(style);
}

function svgEl(tag, attrs = {}) {
  const el = document.createElementNS('http://www.w3.org/2000/svg', tag);
  Object.entries(attrs).forEach(([key, value]) => el.setAttribute(key, String(value)));
  return el;
}

function starPoints(cx, cy, outerR, innerR = outerR * 0.42) {
  const pts = [];
  for (let i = 0; i < 10; i++) {
    const radius = i % 2 === 0 ? outerR : innerR;
    const theta = -Math.PI / 2 + (i * Math.PI) / 5;
    pts.push(`${cx + radius * Math.cos(theta)},${cy + radius * Math.sin(theta)}`);
  }
  return pts.join(' ');
}

function makeSvgIcon(builder) {
  const svg = svgEl('svg', { viewBox: '0 0 52 52', width: 52, height: 52, 'aria-hidden': 'true' });
  builder(svg);
  return svg;
}

function makeDotIcon() {
  return makeSvgIcon((svg) => {
    svg.appendChild(svgEl('circle', { cx: 26, cy: 26, r: 8.5, fill: '#111' }));
  });
}

function makeSquareIcon() {
  return makeSvgIcon((svg) => {
    svg.appendChild(
      svgEl('rect', {
        x: 17,
        y: 17,
        width: 18,
        height: 18,
        fill: 'none',
        stroke: DUMMY_COLOUR,
        'stroke-width': 2.6,
      })
    );
  });
}

function makeStarIcon() {
  return makeSvgIcon((svg) => {
    svg.appendChild(
      svgEl('polygon', {
        points: starPoints(26, 26, 11.5),
        fill: '#111',
      })
    );
  });
}

function makeToneIcon() {
  return makeSvgIcon((svg) => {
    svg.appendChild(svgEl('rect', { x: 11, y: 19, width: 8, height: 14, fill: '#111' }));
    svg.appendChild(svgEl('polygon', { points: '19,17 30,10 30,42 19,35', fill: '#111' }));
    svg.appendChild(
      svgEl('path', {
        d: 'M33 20 Q39 26 33 32',
        fill: 'none',
        stroke: '#111',
        'stroke-width': 2.4,
        'stroke-linecap': 'round',
      })
    );
    svg.appendChild(
      svgEl('path', {
        d: 'M37 15 Q47 26 37 37',
        fill: 'none',
        stroke: '#111',
        'stroke-width': 2.4,
        'stroke-linecap': 'round',
      })
    );
  });
}

function makeIcon(kind) {
  if (kind === 'dot') return makeDotIcon();
  if (kind === 'square') return makeSquareIcon();
  if (kind === 'star') return makeStarIcon();
  if (kind === 'tone') return makeToneIcon();
  throw new Error(`Unknown slot icon kind: ${kind}`);
}

function buildRow(row) {
  const rowEl = document.createElement('div');
  rowEl.className = 'slot-row';

  const label = document.createElement('div');
  label.className = 'slot-label';
  label.textContent = row.label;

  const lane = document.createElement('div');
  lane.className = 'slot-lane';

  EXAMPLE_SEQUENCE.forEach((slotKind) => {
    const iconKind = row.mapping[slotKind];
    const cell = document.createElement('div');
    cell.className = 'slot-cell';

    const icon = document.createElement('div');
    icon.className = 'slot-icon';
    icon.appendChild(makeIcon(iconKind));

    cell.append(icon);
    lane.appendChild(cell);
  });

  rowEl.append(label, lane);
  return rowEl;
}

function buildHeaderRow() {
  const rowEl = document.createElement('div');
  rowEl.className = 'slot-row slot-row-header';

  const spacer = document.createElement('div');

  const strip = document.createElement('div');
  strip.className = 'slot-header-strip';
  for (let i = 1; i <= 6; i++) {
    const cell = document.createElement('div');
    cell.className = 'slot-header-cell';
    cell.textContent = String(i);
    strip.appendChild(cell);
  }

  rowEl.append(spacer, strip);
  return rowEl;
}

function buildFigure() {
  injectStyles();

  const root = document.getElementById('slot-sequence-figure');
  const shell = document.createElement('div');
  shell.className = 'slot-shell';

  const title = document.createElement('div');
  title.className = 'slot-title';
  title.textContent = 'Illustrative Six-Slot Event Sequence by Trial Type';

  shell.append(title);
  shell.appendChild(buildHeaderRow());
  ROWS.forEach((row) => shell.appendChild(buildRow(row)));
  root.appendChild(shell);

  document.body.dataset.captureReady = 'true';
}

buildFigure();
